/**
 * Measures complete N-Quads documents, including writer construction, version announcements and the final flush. Values
 * are created once per trial; both output paths consume every emitted byte or character with bounded reusable checksum
 * state. Run with {@code -prof gc} to report allocation per statement as well as statements per second. The default
 * matrix uses Unicode escaping; select {@code -p escapeUnicode=false} for the unescaped path.
 */
@State(Scope.Thread)
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(value = 2, jvmArgs = { "-Xms512m", "-Xmx512m" })
public class NQuadsWriterBenchmark {

	private static final int STATEMENTS = 256;

	@Param({ "ASCII_IRI", "ASCII_LITERAL", "ESCAPED", "UNICODE", "LONG_LITERAL", "RDF12" })
	public String dataset;

	@Param({ "OUTPUT_STREAM", "WRITER" })
	public String output;

	@Param({ "true" })
	public boolean escapeUnicode;

	private Statement[] statements;

	private final ChecksumOutputStream bytes = new ChecksumOutputStream();

	private final ChecksumWriter characters = new ChecksumWriter();

	@Setup(Level.Trial)
	public void setup() {
		ValueFactory vf = SimpleValueFactory.getInstance();
		IRI predicate = vf.createIRI("http://example.org/vocabulary/property");
		String longLabel = "abcdefghij0123456789".repeat(820);
		statements = new Statement[STATEMENTS];
		for (int i = 0; i < statements.length; i++) {
			Resource subject = vf.createIRI("http://example.org/subject/" + i);
			Resource graph = i % 4 == 0 ? null : vf.createIRI("http://example.org/graph/" + i % 8);
			Value object;
			switch (dataset) {
			case "ASCII_IRI":
				object = vf.createIRI("http://example.org/object/" + i + "?key=value&next=other");
				break;
			case "ASCII_LITERAL":
				object = i % 2 == 0 ? vf.createLiteral("A short plain literal " + i)
						: vf.createLiteral("A short language literal " + i, "en");
				break;
			case "ESCAPED":
				object = vf.createLiteral("Line " + i + ": \"quoted\"\\path\tvalue\nnext\r\n\b\f");
				break;
			case "UNICODE":
				subject = vf.createIRI("http://example.org/café/日本語/😀/" + i);
				graph = vf.createIRI("http://example.org/graph/Ελληνικά/" + i % 8);
				object = vf.createLiteral("café Ελληνικά 日本語 😀 " + i, "fr");
				break;
			case "LONG_LITERAL":
				object = vf.createLiteral(longLabel + i + "\n\"tail\"\\😀");
				break;
			case "RDF12":
				subject = vf.createBNode("subject" + i);
				TripleTerm inner = vf.createTripleTerm(vf.createBNode("nested" + i), predicate,
						vf.createLiteral("directional " + i, "en", BaseDirection.LTR));
				object = i % 2 == 0 ? inner
						: vf.createTripleTerm(vf.createIRI("http://example.org/quoted/" + i), predicate, inner);
				break;
			default:
				throw new IllegalArgumentException("Unknown dataset: " + dataset);
			}
			statements[i] = vf.createStatement(subject, predicate, object, graph);
		}
	}

	@Benchmark
	@OperationsPerInvocation(STATEMENTS)
	public long write() {
		NQuadsWriter writer;
		boolean outputStream = "OUTPUT_STREAM".equals(output);
		if (outputStream) {
			bytes.reset();
			writer = new NQuadsWriter(bytes);
		} else if ("WRITER".equals(output)) {
			characters.reset();
			writer = new NQuadsWriter(characters);
		} else {
			throw new IllegalArgumentException("Unknown output: " + output);
		}
		writer.getWriterConfig()
				.set(BasicWriterSettings.RDF_OUTPUT_VERSION, VersionLabel.RDF_1_2_FULL)
				.set(BasicWriterSettings.CONVERT_RDF_12_REIFICATION, false)
				.set(BasicWriterSettings.ANNOUNCE_RDF12_VERSION, true)
				.set(BasicWriterSettings.XSD_STRING_TO_PLAIN_LITERAL, true)
				.set(NTriplesWriterSettings.ESCAPE_UNICODE, escapeUnicode);
		writer.startRDF();
		for (Statement statement : statements) {
			writer.handleStatement(statement);
		}
		writer.endRDF();
		return outputStream ? bytes.result() : characters.result();
	}

	private static final class ChecksumOutputStream extends OutputStream {
		private final CRC32 checksum = new CRC32();

		private long count;

		void reset() {
			checksum.reset();
			count = 0;
		}

		long result() {
			return checksum.getValue() ^ count;
		}

		@Override
		public void write(int value) {
			checksum.update(value);
			count++;
		}

		@Override
		public void write(byte[] value, int offset, int length) {
			checksum.update(value, offset, length);
			count += length;
		}
	}

	private static final class ChecksumWriter extends Writer {
		private long checksum;

		private long count;

		void reset() {
			checksum = 1;
			count = 0;
		}

		long result() {
			return checksum ^ count;
		}

		@Override
		public void write(int value) {
			checksum = 31 * checksum + (char) value;
			count++;
		}

		@Override
		public void write(char[] value, int offset, int length) {
			long hash = checksum;
			for (int i = offset, end = offset + length; i < end; i++) {
				hash = 31 * hash + value[i];
			}
			checksum = hash;
			count += length;
		}

		@Override
		public void write(String value, int offset, int length) {
			long hash = checksum;
			for (int i = offset, end = offset + length; i < end; i++) {
				hash = 31 * hash + value.charAt(i);
			}
			checksum = hash;
			count += length;
		}

		@Override
		public void flush() {
		}

		@Override
		public void close() {
		}
	}
}
